import React, { useState } from 'react';
import { VoicePreset, TTSConfig } from '../types';

interface PresetManagerProps {
  currentConfig: Omit<TTSConfig, 'text'>;
  presets: VoicePreset[];
  onSave: (name: string) => void;
  onLoad: (preset: VoicePreset) => void;
  onDelete: (id: string) => void;
  isGenerating: boolean;
}

const PresetManager: React.FC<PresetManagerProps> = ({
  presets,
  onSave,
  onLoad,
  onDelete,
  isGenerating
}) => {
  const [newPresetName, setNewPresetName] = useState('');

  const handleSave = () => {
    if (newPresetName.trim()) {
      onSave(newPresetName.trim());
      setNewPresetName('');
    }
  };

  return (
    <div className="space-y-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
      <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
        <i className="fas fa-bookmark text-indigo-500"></i> My Presets
      </h3>

      <div className="flex gap-2">
        <input
          type="text"
          value={newPresetName}
          onChange={(e) => setNewPresetName(e.target.value)}
          placeholder="Preset name..."
          disabled={isGenerating}
          className="flex-grow px-4 py-2 text-sm border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500"
        />
        <button
          onClick={handleSave}
          disabled={isGenerating || !newPresetName.trim()}
          className="bg-indigo-600 text-white w-10 h-10 rounded-xl flex items-center justify-center hover:bg-indigo-700 disabled:opacity-50 transition-all"
        >
          <i className="fas fa-plus"></i>
        </button>
      </div>

      <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
        {presets.length === 0 ? (
          <p className="text-xs text-gray-400 text-center py-4">No presets saved yet.</p>
        ) : (
          presets.map((preset) => (
            <div
              key={preset.id}
              className="group flex items-center justify-between p-2 rounded-xl border border-gray-100 hover:border-indigo-200 hover:bg-indigo-50/30 transition-all"
            >
              <button
                onClick={() => onLoad(preset)}
                disabled={isGenerating}
                className="flex-grow text-left px-2 py-1"
              >
                <span className="block text-sm font-semibold text-gray-700">{preset.name}</span>
                <span className="block text-[10px] text-gray-400 uppercase tracking-wider">
                  {preset.config.language} • {preset.config.tone}
                </span>
              </button>
              <button
                onClick={() => onDelete(preset.id)}
                disabled={isGenerating}
                className="text-gray-300 hover:text-red-500 px-3 py-2 transition-colors opacity-0 group-hover:opacity-100"
              >
                <i className="fas fa-trash-alt text-xs"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default PresetManager;

