  BANGLA = 'Bangla',
  HINDI = 'Hindi',
  ENGLISH = 'English'
}

export enum VoiceTone {
  NORMAL = 'Normal',
  PROFESSIONAL = 'Professional',
  SOFT = 'Soft'
}

export enum SpeechSpeed {
  SLOW = 'Slow',
  NORMAL = 'Normal',
  FAST = 'Fast'
}

export interface TTSConfig {
  language: Language;
  tone: VoiceTone;
  speed: SpeechSpeed;
  text: string;
  clonedVoiceData?: {
    data: string; // Base64
    mimeType: string;
    fileName: string;
  };
}

export interface VoicePreset {
  id: string;
  name: string;
  config: Omit<TTSConfig, 'text' | 'clonedVoiceData'>;
}

export interface AudioState {
  isPlaying: boolean;
  isGenerating: boolean;
  audioBuffer: AudioBuffer | null;
  error: string | null;
}

import { GoogleGenAI, Modality } from "@google/genai";
import { TTSConfig, Language, VoiceTone, SpeechSpeed } from "../types";
import { decodeBase64, decodePCMToAudioBuffer } from "./audioUtils";

const API_KEY = process.env.API_KEY || "";

export async function generateSpeech(config: TTSConfig, audioContext: AudioContext): Promise<AudioBuffer> {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const isCloning = !!config.clonedVoiceData;

  if (isCloning && config.clonedVoiceData) {
    // Voice Cloning Path: Use Native Audio model
    const prompt = `Listen carefully to the voice in the attached audio sample. 
    Act as a professional voice cloning engine. 
    Read the following text in EXACTLY the same voice, accent, tone, and vocal characteristics as the speaker in the sample. 
    Maintain the emotional depth and pacing of the original speaker.
    Language: ${config.language}
    Text to read: "${config.text}"`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-native-audio-preview-12-2025",
        contents: [{
          parts: [
            {
              inlineData: {
                data: config.clonedVoiceData.data,
                mimeType: config.clonedVoiceData.mimeType,
              },
            },
            { text: prompt },
          ],
        }],
        config: {
          responseModalities: [Modality.AUDIO],
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (!base64Audio) throw new Error("Failed to generate cloned voice audio.");

      const binaryData = decodeBase64(base64Audio);
      return await decodePCMToAudioBuffer(binaryData, audioContext);
    } catch (error: any) {
      console.error("Cloning Error:", error);
      throw new Error(error.message || "An error occurred during voice cloning.");
    }
  } else {
    // Standard TTS Path: Use Prebuilt TTS model
    const speedInstruction = config.speed === SpeechSpeed.SLOW ? "slowly and clearly" : 
                             config.speed === SpeechSpeed.FAST ? "rapidly but clearly" : "at a natural pace";

    const toneInstruction = config.tone === VoiceTone.PROFESSIONAL ? 
      "as a professional news anchor or documentary narrator. Use a confident, clear, and neutral tone. No robotic artifacts." :
      config.tone === VoiceTone.SOFT ? "in a soft, calm, and soothing voice with emotional warmth." :
      "in a normal, engaging conversational tone.";

    const languageContext = config.language === Language.BANGLA ? "Standard Neutral Bangla accent" :
                            config.language === Language.HINDI ? "Standard Hindi accent" : "Neutral English accent";

    const prompt = `Convert the following text into ${config.language} speech. 
    Instruction: Read this ${toneInstruction} ${speedInstruction}. 
    Accent: ${languageContext}.

    Text: "${config.text}"`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("Failed to receive audio data from AI.");

      const binaryData = decodeBase64(base64Audio);
      return await decodePCMToAudioBuffer(binaryData, audioContext);
    } catch (error: any) {
      console.error("TTS Error:", error);
      throw new Error(error.message || "An error occurred during voice generation.");
    }
  }
}

import React, { useRef } from 'react';
