interface ControlPanelProps {
  config: TTSConfig;
  onChange: (config: TTSConfig) => void;
  isGenerating: boolean;
}

const ControlPanel: React.FC<ControlPanelProps> = ({ config, onChange, isGenerating }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const updateConfig = (key: keyof TTSConfig, value: any) => {
    onChange({ ...config, [key]: value });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = (event.target?.result as string).split(',')[1];
      onChange({
        ...config,
        clonedVoiceData: {
          data: base64,
          mimeType: file.type || 'audio/wav',
          fileName: file.name
        }
      });
    };
    reader.readAsDataURL(file);
  };

  const removeClonedVoice = () => {
    const newConfig = { ...config };
    delete newConfig.clonedVoiceData;
    onChange(newConfig);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-full">
