  SOFT = 'Soft'
}

export enum VoiceEmotion {
  NEUTRAL = 'Neutral',
  HAPPY = 'Happy',
  SAD = 'Sad',
  ANGRY = 'Angry',
  EXCITED = 'Excited',
  SERIOUS = 'Serious'
}

export enum SpeechSpeed {
  SLOW = 'Slow',
  NORMAL = 'Normal',
  FAST = 'Fast'
}

export enum VoiceCharacter {
  KORE = 'Kore',
  PUCK = 'Puck',
  CHARON = 'Charon',
  FENRIR = 'Fenrir',
  ZEPHYR = 'Zephyr',
  AOEDE = 'Aoede',
  EOS = 'Eos'
}

export interface TTSConfig {
  language: Language;
  tone: VoiceTone;
  emotion: VoiceEmotion;
  speed: SpeechSpeed;
  voiceCharacter: VoiceCharacter;
  text: string;
  clonedVoiceData?: {
    data: string; // Base64
    mimeType: string;
    fileName: string;
  };
}

export interface VoicePreset {
  id: string;
  name: string;
  config: Omit<TTSConfig, 'text' | 'clonedVoiceData'>;
