import React, { useRef, useState } from 'react';
import { Language, VoiceTone, SpeechSpeed, VoiceCharacter, VoiceEmotion, TTSConfig } from '../types';

interface ControlPanelProps {
  config: TTSConfig;
  onChange: (config: TTSConfig) => void;
  isGenerating: boolean;
}

const ControlPanel: React.FC<ControlPanelProps> = ({ config, onChange, isGenerating }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showCloningGuide, setShowCloningGuide] = useState(false);

  const updateConfig = (key: keyof TTSConfig, value: any) => {
    onChange({ ...config, [key]: value });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = (event.target?.result as string).split(',')[1];
      onChange({
        ...config,
        clonedVoiceData: {
          data: base64,
          mimeType: file.type || 'audio/wav',
          fileName: file.name
        }
      });
    };
    reader.readAsDataURL(file);
  };

  const removeClonedVoice = () => {
    const newConfig = { ...config };
    delete newConfig.clonedVoiceData;
    onChange(newConfig);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getEmotionIcon = (emotion: VoiceEmotion) => {
    switch(emotion) {
      case VoiceEmotion.HAPPY: return 'fa-laugh-beam';
      case VoiceEmotion.SAD: return 'fa-sad-tear';
      case VoiceEmotion.ANGRY: return 'fa-angry';
      case VoiceEmotion.EXCITED: return 'fa-grin-stars';
      case VoiceEmotion.SERIOUS: return 'fa-user-tie';
      default: return 'fa-meh';
    }
  };

  const getCharacterInfo = (char: VoiceCharacter) => {
    switch(char) {
      case VoiceCharacter.KORE: return { icon: 'fa-female', label: 'Clear' };
      case VoiceCharacter.PUCK: return { icon: 'fa-male', label: 'Energetic' };
      case VoiceCharacter.CHARON: return { icon: 'fa-user-tie', label: 'Deep' };
      case VoiceCharacter.FENRIR: return { icon: 'fa-wolf-pack-white', label: 'Strong' };
      case VoiceCharacter.ZEPHYR: return { icon: 'fa-wind', label: 'Soft' };
      case VoiceCharacter.AOEDE: return { icon: 'fa-music', label: 'Melodic' };
      case VoiceCharacter.EOS: return { icon: 'fa-sun', label: 'Bright' };
      default: return { icon: 'fa-user', label: 'AI' };
    }
  };

  return (
    <div className="space-y-6 bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-full overflow-y-auto custom-scrollbar">
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <i className="fas fa-sliders-h text-indigo-500"></i> Voice Settings
        </h3>
      </div>

      {/* Voice Cloning Section */}
      <div className="p-4 rounded-xl border-2 border-dashed border-indigo-100 bg-indigo-50/30 space-y-3 relative overflow-hidden group">
        <div className="absolute top-0 right-0 bg-indigo-600 text-white text-[9px] font-black px-2 py-0.5 rounded-bl-lg uppercase tracking-widest">
          Beta
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 text-indigo-700 font-bold text-xs uppercase tracking-wider">
            <i className="fas fa-fingerprint"></i> Voice Cloning
          </div>
          <button 
            onClick={() => setShowCloningGuide(!showCloningGuide)}
            className="text-[10px] font-bold text-indigo-500 hover:text-indigo-700 underline"
          >
            {showCloningGuide ? 'Hide Tips' : 'Best results?'}
          </button>
        </div>

        {showCloningGuide && (
          <div className="bg-white/80 rounded-lg p-3 text-[11px] text-indigo-900 border border-indigo-100 space-y-2 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="flex gap-2">
              <i className="fas fa-clock text-indigo-500 mt-0.5"></i>
              <p><strong>Length:</strong> 10-30s of clear speech.</p>
            </div>
            <div className="flex gap-2">
              <i className="fas fa-volume-mute text-indigo-500 mt-0.5"></i>
              <p><strong>Environment:</strong> Silence is key.</p>
            </div>
          </div>
        )}

        {config.clonedVoiceData ? (
          <div className="flex items-center justify-between bg-white p-2 rounded-lg border border-indigo-200 shadow-sm">
            <div className="flex items-center gap-2 overflow-hidden">
              <i className="fas fa-file-audio text-indigo-500"></i>
              <span className="text-xs font-medium text-gray-600 truncate">{config.clonedVoiceData.fileName}</span>
            </div>
            <button 
              onClick={removeClonedVoice}
              className="text-gray-400 hover:text-red-500 p-1"
            >
              <i className="fas fa-times-circle"></i>
            </button>
          </div>
        ) : (
          <div>
            <input 
              type="file" 
              accept="audio/*" 
              className="hidden" 
              ref={fileInputRef}
              onChange={handleFileUpload}
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isGenerating}
              className="w-full py-3 bg-white border border-indigo-200 rounded-lg text-xs font-bold text-indigo-600 hover:bg-indigo-50 transition-colors flex items-center justify-center gap-2"
            >
              <i className="fas fa-upload"></i> Upload Voice Sample
            </button>
          </div>
        )}
      </div>

      {!config.clonedVoiceData && (
        <>
          {/* Voice Character Selection */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600">Voice Character Library</label>
            <div className="grid grid-cols-4 gap-2">
              {Object.values(VoiceCharacter).map((char) => {
                const info = getCharacterInfo(char);
                return (
                  <button
                    key={char}
                    disabled={isGenerating}
                    onClick={() => updateConfig('voiceCharacter', char)}
                    title={`${char} - ${info.label}`}
                    className={`flex flex-col items-center py-2 px-1 rounded-xl text-[10px] font-bold border transition-all ${
                      config.voiceCharacter === char
