                    <i className={`fas ${info.icon} mb-1 text-xs`}></i>
                    <span className="truncate w-full text-center">{char}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Language Selection */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600">Language</label>
            <div className="grid grid-cols-3 gap-2">
              {Object.values(Language).map((lang) => (
                <button
                  key={lang}
                  disabled={isGenerating}
                  onClick={() => updateConfig('language', lang)}
                  className={`py-2 px-3 rounded-xl text-xs font-bold border transition-all ${
                    config.language === lang
                      ? 'bg-indigo-600 border-indigo-600 text-white shadow-md'
                      : 'bg-gray-50 border-gray-200 text-gray-600 hover:border-indigo-300'
                  } disabled:opacity-50`}
                >
                  {lang}
                </button>
              ))}
            </div>
          </div>

          {/* Emotion Selection */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600">Vocal Emotion</label>
            <div className="grid grid-cols-3 gap-2">
              {Object.values(VoiceEmotion).map((emotion) => (
                <button
                  key={emotion}
                  disabled={isGenerating}
                  onClick={() => updateConfig('emotion', emotion)}
                  className={`flex items-center justify-center gap-2 py-2 px-1 rounded-xl text-[10px] font-bold border transition-all ${
                    config.emotion === emotion
                      ? 'bg-indigo-50 border-indigo-500 text-indigo-700 shadow-sm'
                      : 'bg-white border-gray-200 text-gray-500 hover:border-indigo-300'
                  } disabled:opacity-50`}
                >
                  <i className={`fas ${getEmotionIcon(emotion)}`}></i>
                  {emotion}
                </button>
              ))}
            </div>
          </div>

          {/* Tone Selection */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600">Tone Preset</label>
            <div className="grid grid-cols-1 gap-2">
              {Object.values(VoiceTone).map((tone) => (
                <button
                  key={tone}
                  disabled={isGenerating}
                  onClick={() => updateConfig('tone', tone)}
                  className={`flex items-center gap-3 py-3 px-4 rounded-xl text-sm font-medium border transition-all ${
                    config.tone === tone
                      ? 'bg-indigo-50 border-indigo-500 text-indigo-700'
                      : 'bg-white border-gray-200 text-gray-600 hover:border-indigo-300'
                  } disabled:opacity-50`}
                >
                  <i className={`fas ${tone === VoiceTone.PROFESSIONAL ? 'fa-broadcast-tower' : tone === VoiceTone.SOFT ? 'fa-feather' : 'fa-smile'} w-5`}></i>
                  <div className="text-left">
                    <span className="block font-bold">{tone}</span>
                    <span className="text-[10px] opacity-70">
                      {tone === VoiceTone.PROFESSIONAL ? 'News / Documentary' : tone === VoiceTone.SOFT ? 'Calm & soothing' : 'Conversational'}
                    </span>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </>
      )}

      {/* Speed Selection */}
      <div className="space-y-2">
        <label className="text-sm font-semibold text-gray-600">Playback Speed</label>
        <div className="flex bg-gray-100 p-1 rounded-xl">
          {Object.values(SpeechSpeed).map((speed) => (
            <button
              key={speed}
              disabled={isGenerating}
              onClick={() => updateConfig('speed', speed)}
              className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${
                config.speed === speed
                  ? 'bg-white text-indigo-600 shadow-sm'
                  : 'text-gray-500 hover:text-gray-700'
              } disabled:opacity-50`}
            >
              {speed}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

