        },
      });

      // Access .text or part data directly (not as a function) as per guidelines
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("Failed to receive audio data from AI.");

      const binaryData = decodeBase64(base64Audio);
      return await decodePCMToAudioBuffer(binaryData, audioContext);
    } catch (error: any) {
      console.error("TTS Error:", error);
      throw new Error(error.message || "An error occurred during voice generation.");
    }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import Header from './components/Header';
import ControlPanel from './components/ControlPanel';
import PresetManager from './components/PresetManager';
import AudioVisualizer from './components/AudioVisualizer';
import { Language, VoiceTone, SpeechSpeed, VoiceCharacter, VoiceEmotion, TTSConfig, AudioState, VoicePreset } from './types';
import { generateSpeech } from './services/geminiTTS';
import { audioBufferToWav } from './components/audioUtils';

const PRESETS_STORAGE_KEY = 'kotha_ai_voice_presets_v3';

const App: React.FC = () => {
  const [config, setConfig] = useState<TTSConfig>({
    language: Language.BANGLA,
    tone: VoiceTone.PROFESSIONAL,
    emotion: VoiceEmotion.NEUTRAL,
    speed: SpeechSpeed.NORMAL,
    voiceCharacter: VoiceCharacter.KORE,
    text: '',
  });

  const [presets, setPresets] = useState<VoicePreset[]>([]);

  const [audioState, setAudioState] = useState<AudioState>({
    isPlaying: false,
    isGenerating: false,
    audioBuffer: null,
    error: null,
  });

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    const savedPresets = localStorage.getItem(PRESETS_STORAGE_KEY);
    if (savedPresets) {
      try {
        setPresets(JSON.parse(savedPresets));
      } catch (e) {
        console.error("Failed to load presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(PRESETS_STORAGE_KEY, JSON.stringify(presets));
  }, [presets]);

  useEffect(() => {
    return () => {
      if (audioSourceRef.current) {
        audioSourceRef.current.stop();
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  const handleGenerate = async () => {
    if (!config.text.trim()) {
      setAudioState(prev => ({ ...prev, error: "Please enter some text to convert." }));
      return;
    }

    setAudioState(prev => ({ 
      ...prev, 
      isGenerating: true, 
      error: null, 
      isPlaying: false,
      audioBuffer: null 
    }));

    if (audioSourceRef.current) {
      audioSourceRef.current.stop();
    }

    try {
      if (!audioContextRef.current) {
        // Initialize AudioContext with 24000 sample rate to match the output from the model
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const buffer = await generateSpeech(config, audioContextRef.current);
      setAudioState(prev => ({ 
        ...prev, 
        audioBuffer: buffer, 
        isGenerating: false 
      }));

      playAudio(buffer);
    } catch (err: any) {
      setAudioState(prev => ({ 
        ...prev, 
        isGenerating: false, 
        error: err.message || "Something went wrong." 
      }));
    }
  };

  const playAudio = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;

    if (audioSourceRef.current) {
      audioSourceRef.current.stop();
    }

    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);

    source.onended = () => {
      setAudioState(prev => ({ ...prev, isPlaying: false }));
    };

    source.start(0);
    audioSourceRef.current = source;
    setAudioState(prev => ({ ...prev, isPlaying: true }));
  };

  const handlePlayPause = () => {
    if (audioState.isPlaying) {
      if (audioSourceRef.current) {
        audioSourceRef.current.stop();
        setAudioState(prev => ({ ...prev, isPlaying: false }));
      }
    } else if (audioState.audioBuffer) {
      playAudio(audioState.audioBuffer);
    }
  };

  const handleDownload = () => {
    if (!audioState.audioBuffer) return;

    try {
      const wavBlob = audioBufferToWav(audioState.audioBuffer);
      const url = URL.createObjectURL(wavBlob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `kotha-ai-voice-${Date.now()}.wav`;
      anchor.click();
      setTimeout(() => URL.revokeObjectURL(url), 100);
    } catch (err) {
      console.error("Download failed:", err);
      setAudioState(prev => ({ ...prev, error: "Failed to process audio for download." }));
    }
  };

  const handleSavePreset = (name: string) => {
    const newPreset: VoicePreset = {
      id: crypto.randomUUID(),
      name,
      config: {
        language: config.language,
        tone: config.tone,
        emotion: config.emotion,
        speed: config.speed,
        voiceCharacter: config.voiceCharacter,
      },
    };
    setPresets(prev => [newPreset, ...prev]);
  };

  const handleLoadPreset = (preset: VoicePreset) => {
    const newConfig = { ...config, ...preset.config };
    delete newConfig.clonedVoiceData;
    setConfig(newConfig);
  };

  const handleDeletePreset = (id: string) => {
    setPresets(prev => prev.filter(p => p.id !== id));
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow max-w-6xl mx-auto w-full p-4 md:p-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 space-y-6">
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="border-b border-gray-50 p-4 flex justify-between items-center bg-gray-50/50">
              <span className="text-sm font-bold text-gray-700 flex items-center gap-2">
                <i className="fas fa-edit text-indigo-500"></i> Script Editor
              </span>
              <div className="flex gap-2">
                <button 
                  onClick={() => setConfig({ ...config, text: '' })}
                  className="text-xs font-bold text-gray-400 hover:text-red-500 transition-colors"
                >
                  <i className="fas fa-trash-alt mr-1"></i> Clear
                </button>
              </div>
            </div>

            <textarea
              className="w-full h-80 p-6 text-lg focus:outline-none resize-none bangla-font text-gray-800"
              placeholder={config.language === Language.BANGLA ? "আপনার স্ক্রিপ্টটি এখানে লিখুন বা পেস্ট করুন..." : "Type or paste your script here..."}
              value={config.text}
              onChange={(e) => setConfig({ ...config, text: e.target.value })}
              disabled={audioState.isGenerating}
            />

            <div className="p-4 bg-white flex items-center justify-between border-t border-gray-50">
              <div className="text-xs text-gray-400 font-medium italic">
                {config.text.length} characters • Voice is AI generated
              </div>
              <button
                onClick={handleGenerate}
                disabled={audioState.isGenerating || !config.text.trim()}
                className={`flex items-center gap-2 px-8 py-3 rounded-2xl font-bold transition-all transform active:scale-95 ${
                  audioState.isGenerating 
                    ? 'bg-indigo-400 cursor-not-allowed text-white' 
                    : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-200'
                }`}
              >
                {audioState.isGenerating ? (
                  <>
                    <i className="fas fa-circle-notch animate-spin"></i>
                    {config.clonedVoiceData ? 'Cloning & Generating...' : 'Synthesizing...'}
                  </>
                ) : (
                  <>
                    <i className="fas fa-magic"></i>
                    Convert to Voice
                  </>
                )}
              </button>
            </div>
          </div>

          {(audioState.audioBuffer || audioState.isGenerating || audioState.error) && (
            <div className={`rounded-3xl p-6 shadow-xl transition-all duration-500 border ${
              audioState.error ? 'bg-red-50 border-red-100' : 'bg-white border-gray-100'
            }`}>
              {audioState.error ? (
                <div className="flex items-center gap-4 text-red-700">
                  <i className="fas fa-exclamation-circle text-2xl"></i>
                  <p className="font-medium">{audioState.error}</p>
                </div>
              ) : (
                <div className="flex flex-col md:flex-row items-center gap-6">
                  <button 
                    onClick={handlePlayPause}
                    disabled={!audioState.audioBuffer}
                    className={`w-16 h-16 rounded-full flex items-center justify-center text-xl transition-all shadow-lg ${
                      audioState.isPlaying 
                        ? 'bg-indigo-100 text-indigo-700' 
                        : 'bg-indigo-600 text-white hover:bg-indigo-700'
                    } disabled:bg-gray-100 disabled:text-gray-300`}
                  >
                    <i className={`fas ${audioState.isPlaying ? 'fa-pause' : 'fa-play ml-1'}`}></i>
                  </button>

                  <div className="flex-grow space-y-2 w-full">
                    <div className="flex justify-between items-end">
                      <div>
                        <h4 className="font-bold text-gray-800">
                          {audioState.isGenerating ? (config.clonedVoiceData ? 'Cloning voice identity...' : 'Synthesizing voice...') : 'Preview Output'}
                        </h4>
                        <p className="text-xs text-gray-500">
                          {config.clonedVoiceData ? 'Cloned Voice' : config.language} • {config.tone} • {config.emotion} • {config.speed} • {config.voiceCharacter}
                        </p>
                      </div>
                      {audioState.audioBuffer && !audioState.isGenerating && (
                        <button 
                          onClick={handleDownload}
                          className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full hover:bg-indigo-100 transition-colors"
                        >
                          <i className="fas fa-download mr-1"></i> Save Audio
                        </button>
                      )}
                    </div>
                    <AudioVisualizer isPlaying={audioState.isPlaying} isGenerating={audioState.isGenerating} />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="lg:col-span-4 space-y-6">
          <ControlPanel config={config} onChange={setConfig} isGenerating={audioState.isGenerating} />
          <PresetManager 
            currentConfig={{ language: config.language, tone: config.tone, emotion: config.emotion, speed: config.speed, voiceCharacter: config.voiceCharacter }}
            presets={presets}
            onSave={handleSavePreset}
            onLoad={handleLoadPreset}
            onDelete={handleDeletePreset}
            isGenerating={audioState.isGenerating}
          />
        </div>
      </main>

      <footer className="py-6 px-6 text-center text-gray-400 text-xs mt-auto">
        <p>&copy; 2024 Kotha AI. All rights reserved. • Powered by Gemini AI</p>
        <p className="mt-1">Voices are AI generated. Use responsibly.</p>
      </footer>
    </div>
  );
};

export default App;
